        let keypair = generate_wireguard_keypair();
        assert_eq!(keypair.private_key.len(), 44);
        assert_eq!(keypair.public_key.len(), 44);
    }

    #[test]
    fn generates_magic_token_with_requested_length() {
        let token=***        assert_eq!(token.len(), 32);
    }
}

